import math
class Solution:
    def triangleAngles(self, sides):
        a, b, c = sorted(sides)
        if a + b <= c:
            return []
        def ang(x, y, z):
            cosv = (y*y + z*z - x*x) / (2 * y * z)
            cosv = max(-1.0, min(1.0, cosv))
            return math.degrees(math.acos(cosv))
        return sorted([ang(a, b, c), ang(b, a, c), ang(c, a, b)])

