class Solution {
public:
    vector<double> triangleAngles(vector<int>& sides) {
        vector<double> s(sides.begin(), sides.end());
        sort(s.begin(), s.end());
        if (s[0] + s[1] <= s[2]) return {};
        auto ang = [](double x, double y, double z) {
            double c = (y*y + z*z - x*x) / (2 * y * z);
            c = max(-1.0, min(1.0, c));
            return acos(c) * 180.0 / acos(-1.0);
        };
        vector<double> res = {ang(s[0], s[1], s[2]), ang(s[1], s[0], s[2]), ang(s[2], s[0], s[1])};
        sort(res.begin(), res.end());
        return res;
    }
};

