class Solution {
    public double[] triangleAngles(int[] sides) {
        double[] s = new double[3];
        for (int i = 0; i < 3; i++) s[i] = sides[i];
        java.util.Arrays.sort(s);
        if (s[0] + s[1] <= s[2]) return new double[0];
        double[] res = new double[3];
        for (int i = 0; i < 3; i++) {
            double x = s[i], y = s[(i+1)%3], z = s[(i+2)%3];
            double c = (y*y + z*z - x*x) / (2 * y * z);
            c = Math.max(-1.0, Math.min(1.0, c));
            res[i] = Math.toDegrees(Math.acos(c));
        }
        java.util.Arrays.sort(res);
        return res;
    }
}

