var triangleAngles = function(sides) {
    const s = [...sides].sort((a, b) => a - b);
    if (s[0] + s[1] <= s[2]) return [];
    const ang = (x, y, z) => {
        let c = (y*y + z*z - x*x) / (2 * y * z);
        c = Math.max(-1, Math.min(1, c));
        return Math.acos(c) * 180 / Math.PI;
    };
    return [ang(s[0], s[1], s[2]), ang(s[1], s[0], s[2]), ang(s[2], s[0], s[1])].sort((a, b) => a - b);
};
